+const prisma = new PrismaClient()
+
+// Create MCP server
+const server = new Server(
+  {
+    name: 'copamundial-mcp',
+    version: '2.0.0',
+  },
+  {
+    capabilities: {
+      tools: {},
+      resources: {},
+      prompts: {},
+    },
+  }
+)
+
+// ==================== TOOLS ====================
+
+// Tool: Create Team
+server.tool(
+  'create_team',
+  'Create a new sports team with specified configuration',
+  {
+    name: z.string().min(1).max(100),
+    bio: z.string().max(500).optional(),
+    location: z.string().max(100).optional(),
+    formation: z.string().default('4-4-2'),
+    isPrivate: z.boolean().default(false),
+    creatorId: z.string(),
+  },
+  async (params) => {
+    try {
+      const team = await prisma.team.create({
+        data: {
+          name: params.name,
+          bio: params.bio,
+          location: params.location,
+          formation: params.formation,
+          isPrivate: params.isPrivate,
+          createdBy: params.creatorId,
+        },
+        include: {
+          creator: {
+            select: {
+              id: true,
+              name: true,
+            },
+          },
+        },
+      })
+
+      return {
+        success: true,
+        team,
+        message: `Team "${params.name}" created successfully`,
+      }
+    } catch (error) {
+      return {
+        success: false,
+        error: error instanceof Error ? error.message : 'Failed to create team',
+      }
+    }
+  }
+)
+
+// Tool: Find Teams
+server.tool(
+  'find_teams',
+  'Search for teams matching specified criteria',
+  {
+    search: z.string().optional(),
+    location: z.string().optional(),
+    minRating: z.number().optional(),
+    sport: z.string().optional(),
+    limit: z.number().default(20),
+  },
+  async (params) => {
+    try {
+      const where: any = {}
+
+      if (params.search) {
+        where.name = { contains: params.search, mode: 'insensitive' }
+      }
+
+      if (params.location) {
+        where.location = { contains: params.location, mode: 'insensitive' }
+      }
+
+      if (params.minRating) {
+        where.rating = { gte: params.minRating }
+      }
+
+      const teams = await prisma.team.findMany({
+        where,
+        take: params.limit,
+        include: {
+          creator: {
+            select: {
+              id: true,
+              name: true,
+            },
+          },
+          captains: {
+            select: {
+              id: true,
+              name: true,
+            },
+          },
+          _count: {
+            select: {
+              members: true,
+            },
+          },
+        },
+        orderBy: {
+          rating: 'desc',
+        },
+      })
+
+      return {
+        success: true,
+        teams: teams.map((t) => ({
+          ...t,
+          memberCount: t._count.members,
+        })),
+        count: teams.length,
