+        0
+      )
+
+      // Calculate recent performance (last 10 matches)
+      const recentMatches = player.matchParticipants.slice(0, 10)
+      const recentRating =
+        recentMatches.reduce((sum, mp) => sum + (mp.rating || 0), 0) /
